export default function nextUrl({values,previousState}) {
 if(!Array.isArray(values)) throw Error('Invalid URL sheet');
 const index=previousState?.index??0;
 if(!Number.isInteger(index)||index<0) throw Error('Invalid monitor state');
 if(values.length===0) return {state:{index:0},more:false,url:'https://unused.invalid',count:0};
 const header=values[0]; if(!Array.isArray(header)||header.filter(x=>x==='URLS').length!==1) throw Error('Sheet needs one URLS header');
 const column=header.indexOf('URLS'); const rows=values.slice(1).filter(row=>Array.isArray(row)&&row.some(x=>x!==''&&x!==null));
 if(index>=rows.length) return {state:{index},more:false,url:'https://unused.invalid',count:index};
 const url=rows[index][column]; if(typeof url!=='string'||!url.trim()||/[\r\n]/.test(url)) throw Error('Every row needs a URL');
 if(!/^https?:\/\/[^\/?#@\s]+(?:[\/?#][^\s]*)?$/i.test(url)) throw Error('Every URL must be HTTP or HTTPS without credentials');
 return {state:{index:index+1},more:true,url,count:index+1};
}

